import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    p = data[0]
    out = []
    idx = 1
    for _ in range(p):
        L = data[idx]
        A = data[idx + 1]
        B = data[idx + 2]
        idx += 3

        N = B - A + 1

        def f(t):
            return A * t + t * (t - 1) // 2

        if f(N) < L:
            out.append(str(N))
            continue

        lo, hi = 1, N
        while lo < hi:
            mid = (lo + hi) // 2
            if f(mid) >= L:
                hi = mid
            else:
                lo = mid + 1

        out.append(str(lo))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
